'use strict';
/* Kenney Particle Pack CC0-1.0 (source: https://github.com/Calinou/kenney-particle-pack)
 * Embedded original 512x512 PNGs for offline-capable same-origin Android AR.
 * No new network domains, storage permissions, or runtime licensing dependencies.
 */
(function(root){
 const encoded={spark:"",light:""};
 const images={},tintCache=new Map();
 let init=false;
 function load(){
  if(init)return;init=true;
  if(typeof Image==='undefined')return;
  for(const [name,data] of Object.entries(encoded)){
   const img=new Image();
   img.onload=()=>{images[name]=img;tintCache.clear()};
   img.onerror=()=>{images[name]=null};
   img.src='data:image/png;base64,'+data;
  }
 }
 function colored(name,color){
  const img=images[name];if(!img||!img.complete)return null;
  const key=name+':'+color;if(tintCache.has(key))return tintCache.get(key);
  try{
   const c=document.createElement('canvas');c.width=128;c.height=128;
   const g=c.getContext('2d');
   g.clearRect(0,0,128,128);g.drawImage(img,0,0,128,128);
   g.globalCompositeOperation='source-in';g.fillStyle=color;g.fillRect(0,0,128,128);
   g.globalCompositeOperation='source-over';tintCache.set(key,c);
   return c;
  }catch(_){return null}
 }
 root.RitmoKenneyVFX={load,colored,loaded:()=>Object.keys(images).filter(k=>images[k]).length,source:'Kenney Particle Pack CC0'};
})(window);
